#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-10

# strict-mode: opt-out this harness counts failures and prints a summary, so
# `-e` would abort on the first failing assertion. `set -uo pipefail` below.
#
# =============================================================================
# Tests must not WRITE to a hardcoded /tmp path (#4026)
# =============================================================================
# Two defects, and the quiet one is worse.
#
#   1. The CC sandbox denies writes to /tmp, so a test using it fails locally
#      with "Operation not permitted" while passing in CI. Eight tests did.
#   2. The filenames were FIXED (/tmp/watch-out.txt, /tmp/stamp-out.txt). Two
#      concurrent runs on one machine wrote and read the same file, so a test
#      could assert against another run's output and PASS.
#
# `${TMPDIR:-/tmp}` alone fixes only the first. `mktemp` fixes both.
#
# WHY THIS MATCHES WRITE SHAPES AND NOT THE SUBSTRING
#
# The obvious rule, "no /tmp/ anywhere under tests/", is wrong, and I wrote it
# into the issue before measuring. Most /tmp in tests/ is FIXTURE DATA:
#
#   input='{"tool_name":"Write","tool_input":{"file_path":"/tmp/x.txt"}}'
#
# That never touches disk; it is a string a hook classifies. Rewriting it
# changes what the test asserts. Two cases are actively load-bearing:
# tests/skills/test-dashboard-specs.sh passes a /tmp path that must NOT exist,
# and tests/security/test-egress-guard.sh carries a REMOTE scp destination.
#
# So this greps redirects, mktemp, rm -f, mkdir and cp/mv TARGETS. A rule that
# forced fixtures to change is a rule people route around.
# =============================================================================

set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
cd "$REPO_ROOT"

RED=$'\033[0;31m'; GREEN=$'\033[0;32m'; NC=$'\033[0m'
PASS=0; FAIL=0
pass() { echo "  ${GREEN}PASS${NC} $1"; PASS=$((PASS + 1)); }
fail() { echo "  ${RED}FAIL${NC} $1"; FAIL=$((FAIL + 1)); }

echo "=========================================="
echo "  no hardcoded /tmp writes in tests (#4026)"
echo "=========================================="

# Redirect target, mktemp argument, rm -f target, mkdir target, cp/mv target.
SHAPES='(>>?[[:space:]]*"?/tmp/|mktemp[^|]*[[:space:]]/tmp/|rm[[:space:]]+-[a-zA-Z]*f[a-zA-Z]*[[:space:]]+"?/tmp/|mkdir[^|]*[[:space:]]"?/tmp/|(cp|mv)[[:space:]][^|]*[[:space:]]"?/tmp/)'
INC=(--include='*.sh' --include='*.mjs' --include='*.js')

# Lines that are hook INPUT rather than shell. A write shape can appear inside
# a JSON fixture: tests/unit/test-permission-posttool-hooks.sh:277 carries
# {"tool_input":{"command":"rm -rf /tmp/files"}}, which is a string the guard
# under test classifies, not a command this file runs. Found by this very
# scan's first run, which is the argument for keeping the controls below.
FIXTURE_MARKERS='tool_input|file_path|tool_name|"command"'

scan() {
  local hits
  hits=$(grep -rnE "$SHAPES" "$1" "${INC[@]}" 2>/dev/null) || hits=""  # silent: known-noise no matches is the PASS case, so grep's exit 1 is expected
  # Drop $TMPDIR forms, JSON fixtures, and this file's own planted controls.
  printf '%s' "$hits" | grep -vE "TMPDIR|$FIXTURE_MARKERS|test-no-hardcoded-tmp-writes" || printf ''  # silent: known-noise an empty result is the PASS case
}

OFFENDERS="$(scan tests)"
if [[ -z "$OFFENDERS" ]]; then
  pass "no test writes to a hardcoded /tmp path"
else
  fail "test(s) write to a hardcoded /tmp path:"
  printf '%s\n' "$OFFENDERS" | sed 's/^/         /'
  echo "         Use: D=\$(mktemp -d \"\${TMPDIR:-/tmp}/ork-x.XXXXXX\"); trap 'rm -rf \"\$D\"' EXIT"
fi

# ─── controls: a grep that matches nothing looks identical to a grep that
#     is broken, so prove it fires AND that it does not over-fire ────────
TMP="$(mktemp -d "${TMPDIR:-/tmp}/ork-tmpguard.XXXXXX")"
trap 'rm -rf "$TMP"' EXIT

# Control A: a FIXTURE STRING must stay green. This is the whole reason the
# rule is shaped this way, and it is what stops a future "simplification"
# back to a bare substring match.
cat > "$TMP/fixture-only.sh" <<'FIXTURE'
#!/usr/bin/env bash
input='{"tool_name":"Write","tool_input":{"file_path":"/tmp/test.txt"}}'
echo "a path that must not exist: /tmp/does-not-exist.json"
FIXTURE
if [[ -z "$(scan "$TMP/fixture-only.sh")" ]]; then
  pass "a fixture string mentioning /tmp is NOT flagged"
else
  fail "a fixture string was flagged; the rule would force breaking test data"
fi

# Control D: a write shape embedded in a JSON FIXTURE must stay green. This one
# is not hypothetical: the first run of this scan flagged
# tests/unit/test-permission-posttool-hooks.sh for exactly this, an `rm -rf` the
# test feeds to a guard as data.
cat > "$TMP/fixture-command.sh" <<'JSONCMD'
#!/usr/bin/env bash
input='{"tool_name":"Bash","tool_input":{"command":"rm -rf /tmp/files"}}'
JSONCMD
if [[ -z "$(scan "$TMP/fixture-command.sh")" ]]; then
  pass "a write shape inside a JSON fixture is NOT flagged"
else
  fail "a JSON fixture command was flagged; the rule would break hook input data"
fi

# Control B: a planted WRITE must go red, or the scan proves nothing.
cat > "$TMP/planted-write.sh" <<'PLANT'
#!/usr/bin/env bash
node script.mjs > /tmp/planted-out.txt 2>&1
PLANT
if [[ -n "$(scan "$TMP/planted-write.sh")" ]]; then
  pass "a planted redirect to /tmp IS flagged"
else
  fail "a planted redirect to /tmp was not flagged; the pattern is broken"
fi

# Control C: the correct form must not be flagged, or every file this PR just
# fixed would immediately re-offend.
cat > "$TMP/correct-form.sh" <<'GOOD'
#!/usr/bin/env bash
D="$(mktemp -d "${TMPDIR:-/tmp}/ork-x.XXXXXX")"
node script.mjs > "$D/out.txt" 2>&1
GOOD
if [[ -z "$(scan "$TMP/correct-form.sh")" ]]; then
  pass "the mktemp/TMPDIR form is NOT flagged"
else
  fail "the correct form was flagged; the fix would not satisfy its own guard"
fi

echo "=========================================="
echo "  Passed: $PASS  Failed: $FAIL"
echo "=========================================="
[[ $FAIL -eq 0 ]]
